with open('scratch/b19_r07_raw_p5.json') as f:
    raw_p5 = json.load(f)

assert len(reviewed_p5) == 100, f"Expected 100, got {len(reviewed_p5)}"
assert len(raw_p5) == 100, f"Expected 100 raw, got {len(raw_p5)}"

for i, (rev, raw) in enumerate(zip(reviewed_p5, raw_p5)):
    assert rev['id'] == raw['id'], f"ID mismatch at {i}: {rev['id']} vs {raw['id']}"
    assert rev['hw'] == raw['hw'], f"hw mismatch at {i}: {rev['hw']} vs {raw['hw']}"
    assert rev['ipa'].startswith('/') and rev['ipa'].endswith('/') and len(rev['ipa']) > 2, f"ipa format error at {i}: {rev['ipa']}"
    assert rev['ipa'].count('/') == 2, f"ipa slash count != 2 at {i}: {rev['ipa']}"
    assert rev['pos'] in ['noun', 'verb', 'adj', 'adv', 'num', 'intj', 'prep', 'pron', 'conj', 'det'], f"invalid pos at {i}: {rev['pos']}"
    assert rev['vi'] and len(rev['vi']) <= 35, f"vi length > 35 at {i}: {rev['vi']} (len {len(rev['vi'])})"
    assert not any(artifact in rev['vi'] for artifact in ['Số nhiều của', 'Dạng', 'Xem ', 'Viết tắt', '%%']), f"artifact in vi at {i}: {rev['vi']}"

print("Part 5 validated successfully!")